class Sale {
    double price;
    Sale(double p) { price = p; }
    double bill() { return price; }
    boolean lessThan(Sale other) { return bill() < other.bill(); }
}
class DiscountSale extends Sale {
    double discount;
    DiscountSale(double p, double d) { super(p); discount = d; }
    double bill() { return (1 - discount / 100) * price; }
}
public class Main {
    public static void main(String[] args) {
        Sale simple = new Sale(10.00);
        Sale disc = new DiscountSale(11.00, 10);
        System.out.println(simple.lessThan(disc) + " " + disc.lessThan(simple));
    }
}

