@FunctionalInterface
interface Calc {
    int apply(int x);
    default int twice(int x) { return apply(apply(x)); }
    static Calc identity() { return x -> x; }
}
public class Main {
    public static void main(String[] args) {
        Calc inc = x -> x + 1;
        System.out.println(inc.twice(5) + Calc.identity().apply(3));
    }
}

