import java.util.*;
import java.util.stream.*;
public class Main {
    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>(List.of(4, 1, 3, 2));
        int r = nums.stream().map(n -> n * n)
                    .filter(n -> n % 2 == 0)
                    .reduce(0, Integer::sum);
        List<Integer> sorted = nums.stream().sorted().collect(Collectors.toList());
        System.out.println(r + " " + nums + " " + sorted);
    }
}

